import sys

def main():
    line = sys.stdin.readline().strip()
    if not line:
        print("Not Anagram")
        return

    parts = line.split()
    if len(parts) != 2:
        print("Not Anagram")
        return

    word1, word2 = parts[0], parts[1]

    freq = [0] * 26

    for ch in word1:
        freq[ord(ch) - ord('a')] += 1

    for ch in word2:
        freq[ord(ch) - ord('a')] -= 1

    for count in freq:
        if count != 0:
            print("Not Anagram")
            return

    print("Anagram")

if __name__ == "__main__":
    main()
